import bisect, hashlib
H = lambda s: int(hashlib.md5(s.encode()).hexdigest(), 16)

class Ring:
    def __init__(self, nodes, v=128):
        self.pts = sorted((H(f'{n}#{i}'), n) for n in nodes for i in range(v))
        self.keys = [p for p, _ in self.pts]
    def owner(self, key):
        i = bisect.bisect(self.keys, H(key)) % len(self.keys)
        return self.pts[i][1]

upstream cache_pool {
    hash $request_uri consistent;   # Ketama-compatible ring
    server cache1:11211;
    server cache2:11211;
    server cache3:11211;
}
